<?php
require_once __DIR__.'/_bootstrap.php';
$project=getenv('FCM_PROJECT_ID')?:'';$bearer=getenv('FCM_BEARER_TOKEN')?:'';
$q=$conn->query("SELECT pe.*,pt.token FROM push_envios pe JOIN push_tokens pt ON pt.usuario_id=pe.usuario_id AND pt.ativo=1 WHERE pe.status IN ('PENDENTE','ERRO') AND pe.tentativa<5 ORDER BY pe.id ASC LIMIT 50");
while($r=$q->fetch_assoc()){$id=(int)$r['id'];if($project===''||$bearer===''){echo "Push $id pendente: configure FCM_PROJECT_ID e FCM_BEARER_TOKEN\n";continue;}$conn->query("UPDATE push_envios SET status='ENVIANDO',tentativa=tentativa+1 WHERE id=$id");try{$payload=json_encode(['message'=>['token'=>$r['token'],'notification'=>['title'=>$r['titulo'],'body'=>$r['mensagem']?:$r['titulo']],'data'=>['evento_id'=>(string)($r['evento_id']??''),'prioridade'=>$r['prioridade']]]],JSON_UNESCAPED_UNICODE);$url='https://fcm.googleapis.com/v1/projects/'.rawurlencode($project).'/messages:send';$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$bearer],CURLOPT_POSTFIELDS=>$payload,CURLOPT_TIMEOUT=>20]);$resp=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);if($resp===false||$code<200||$code>=300)throw new RuntimeException('FCM HTTP '.$code.' '.substr((string)$resp,0,500));$conn->query("UPDATE push_envios SET status='ENVIADO',erro=NULL,enviado_em=NOW() WHERE id=$id");echo "Push $id enviado\n";}catch(Throwable $e){$err=$conn->real_escape_string(substr($e->getMessage(),0,2000));$conn->query("UPDATE push_envios SET status='ERRO',erro='$err' WHERE id=$id");echo "Push $id erro\n";}}
